import {readFile,writeFile} from 'node:fs/promises';
import {animals,buildings,buildingUpgrade,capacity,crops,cropWeatherProfiles,gameDay,goods,newFarm,recipes,recipeCategory,slotLength,weather,xpRewards} from '../public/game.mjs';
import {aquatic,fishing} from '../public/aqua.mjs';
import {gardenHelperActions,gardenHelperLimit} from '../public/garden-helper.mjs';
import {workCost} from '../public/wellness.mjs';
import {parcelCoopLevels} from '../public/land.mjs';

const out=new URL('../docs/GAMEPLAY_CATALOG.md',import.meta.url);
const lines=[
  '<!-- Generated by scripts/gameplay-docs.mjs. Do not edit numeric tables by hand. -->',
  '# Dữ liệu gameplay lấy trực tiếp từ source','',
  'Xuất lại: `npm run gameplay:docs`. Kiểm tra đồng bộ: `npm run check:gameplay-docs`. Không có ngày sinh file để tránh thay đổi vô nghĩa giữa các lần chạy. Khi thay luật, cập nhật thêm [tài liệu gameplay](GAMEPLAY_REFERENCE.md).','',
  `Một ngày game: ${gameDay/3600} giờ thực. Một ô thời tiết: ${slotLength/3600} giờ thực.`,
];
const table=(title,header,rows)=>{
  lines.push('',`## ${title}`,'','| '+header.join(' | ')+' |','| '+header.map(()=> '---').join(' | ')+' |',...rows.map(r=>'| '+r.join(' | ')+' |'));
};
const name=key=>goods[key]?.name??key;
const items=obj=>Object.entries(obj??{}).map(([key,count])=>`${count} ${name(key)}`).join(', ')||'—';
table('Chuồng phụ',['Cấp','Sức chứa','Giá nâng từ cấp trước','Chuồng chính cần'],parcelCoopLevels.map((level,index)=>[index+1,level.capacity,level.cost??'—',level.coop??'—']));
lines.push('','Chuồng phụ cũ mặc định cấp 1. Nâng riêng từng ô tại Nông trại → Đất; không tự tăng sức chứa khi nâng chuồng chính. Điều kiện loài vật nuôi vẫn theo cấp chuồng chính và XP.');
table('Cây trồng',['Cây','Giống (xu)','Bán/món','Phút cơ sở','Yield nền','XP cần','Xưởng cần','Nhóm trời'],Object.entries(crops).map(([key,d])=>[name(key),goods[d.seed].buy,goods[key].sell,d.time/60,d.yield,d.xp??0,d.workshop??0,cropWeatherProfiles[d.weather].label]));
lines.push('','Yield nền chưa tính phân, thời tiết, sâu/cỏ hoặc phần bị lấy. XP cần là điều kiện mở khóa, không phải XP thưởng thu. Xưởng cần 0 nghĩa là không yêu cầu xưởng.');
table('Vật nuôi',['Con','Giá đón','Chuồng cần','XP cần','Lớn (phút)','Kỳ (phút)','Sản phẩm','Yield nền','Thức ăn/lần','Loại'],Object.values(animals).map(d=>[d.name,d.cost,d.level,d.xp??0,d.grow/60,d.time/60,name(d.product),d.yield,d.food,d.oneTime?'Xuất một lần':'Lặp kỳ']));
lines.push('','Lần thu đầu cần cả giai đoạn lớn và kỳ sản phẩm, chịu thời tiết và khoảng được cho ăn. Con lặp kỳ còn chịu lão hóa; không cộng doanh thu của nhiều kỳ mà bỏ chi phí thức ăn/thời gian.');
table('Nuôi ao',['Loài','Giá giống','Bán/món','Phút cơ sở','Yield/giống','Thức ăn/giống','XP cần','Kho cần','Câu ao khách'],Object.entries(aquatic).map(([key,d])=>[d.name,goods[d.seed].buy,goods[key].sell,d.time/60,d.yield,d.food,d.xp??0,d.barn??1,d.canFish===false?'Không':'Có, nếu đủ điều kiện']));
lines.push('',`Câu hồ làng: chờ ${fishing.wait} giây; cửa sổ kéo ${fishing.window} giây; cooldown ${fishing.cooldown} giây; ${fishing.limit} lượt thành công/ngày game trước thưởng Bến cá.`);
table('Công thức',['Món','Nhóm','Cấp xưởng','Nguyên liệu / 1 món','Giá bán','Hồi nước','Hồi no','Hồi thể lực'],Object.entries(recipes).map(([key,d])=>[name(key),recipeCategory(d)==='materials'?'Vật liệu':'Đồ ăn',d.level,items(d.ingredients),goods[key].sell??'Không bán',d.gain?.water??0,d.gain?.food??0,d.gain?.stamina??0]));
lines.push('','Bảng chỉ là recipe/gain, không khẳng định tất cả đồ ăn đều bán được. Chế tạo hiện không có timer máy riêng.');
table('Thời tiết chung',['Trời','Tốc độ cây','Tốc độ con','Tốc độ ao','Đất ướt'],weather.map(d=>[d.name,d.crop,d.animal,d.water,d.wet?'Có':'Không']));
table('Hệ số riêng theo nhóm cây',['Nhóm','Tăng trưởng khác 1','Sản lượng khác 1'],Object.values(cropWeatherProfiles).map(d=>[d.label,Object.entries(d.growth).map(([k,v])=>`${k}: ${v}`).join('; '),Object.entries(d.yield).map(([k,v])=>`${k}: ${v}`).join('; ')]));
lines.push('','Mã trời: sun=nắng nhẹ, rain=mưa, cloud=mây, heat=nóng, wind=gió, fog=sương, storm=dông. Tốc độ cây còn nhân thời tiết chung, độ ẩm, phân và áp lực; yield riêng không nhân hệ số tốc độ chung.');
const upgrades=[];
for(const [key,def] of Object.entries(buildings)){
  const base=def.base??1;
  for(let level=base;level<base+def.costs.length;level++){
    const farm={...newFarm('catalog','Catalog',0,'female'),[key]:level};
    const step=buildingUpgrade(farm,key);
    upgrades.push([def.name,`${level} → ${level+1}`,step.cost,step.xp,items(step.materials),step.nextBenefit??'—']);
  }
}
table('Các lần nâng công trình',['Công trình','Cấp','Xu','XP cần','Vật liệu','Mốc tiếp theo'],upgrades);
table('Sức chứa Kho',['Cấp','Nông sản'],Array.from({length:buildings.barn.costs.length+1},(_,i)=>[i+1,capacity({barn:i+1})]));
table('XP thưởng theo hành động',['Action','XP'],Object.entries(xpRewards));
table('Tiêu hao theo thao tác, trời thường',['Action','Nước','No','Thể lực'],['till','weed','plant','water','fertilize','spray','harvest','feed','collect','aquaStock','aquaFeed','aquaHarvest','cast','reel','steal','buildLand','upgrade','decorate'].map(action=>{const d=workCost(action,'sun');return[action,d.water,d.food,d.stamina]}));
lines.push('','Trời heat tăng thêm 1 nước cho mỗi action có chi phí. Bảng không có nghĩa mọi action đều được phép ở mọi scene.');
table('Thuê Cô Lan',['Việc','Xu/ô','Giây làm/ô','Tối đa ô/lượt'],Object.values(gardenHelperActions).map(d=>[d.label,d.fee,d.work,gardenHelperLimit]));
lines.push('','Thời gian thuê còn cộng di chuyển, không phải toàn lượt chỉ bằng giây làm × số ô.','');
const content=lines.join('\n');
if(process.argv.includes('--check')){
  let current='';try{current=(await readFile(out,'utf8')).replaceAll('\r\n','\n')}catch(error){if(error.code!=='ENOENT')throw error}
  if(current!==content){console.error('GAMEPLAY_CATALOG.md is stale. Run npm run gameplay:docs');process.exitCode=1}
  else console.log('Gameplay catalog matches source');
}else{await writeFile(out,content);console.log('Generated docs/GAMEPLAY_CATALOG.md')}
